// Verify HMAC-SHA256 Signature
const crypto = require('crypto');
const secret = 'YOUR_BCOS_WEBHOOK_SECRET';
const signature = $request.headers['x-bcos-signature'];
const expectedSignature = crypto.createHmac('sha256', secret).update(JSON.stringify($json)).digest('hex');

if (signature !== expectedSignature) {
  throw new Error('Invalid signature!');
}

return $json;
